/*
 * netlog/test/test_netlog_data.c - the NETLOG module data (source-iq58)
 *
 * Generated by: Claude Opus 5.5
 *
 * netlog/netlog_data.c is #included, so the objects under test are the real
 * definitions with the image's initial contents:
 *
 *   NETLOG_$DATA  0x00E85684, map "D E85684 NETLOG size = 84"
 *   NETLOG_$EC    0x00E248E8, inside "D E248E0 NETLOG_ASM size = 1C"
 *
 * Facts under test:
 *   - NETLOG_$DATA is 0x84 bytes with every field at its A5 displacement
 *     (pointer-free, so this holds on the host too);
 *   - its Pascal [1..2] tables are declared at their bias slots, so the index
 *     the code computes addresses the image's element:
 *       buffer_va[i]    A5 + 0x54 + i*4   (0x00E71C46)
 *       buffer_ppn[i]   A5 + 0x5C + i*4   (0x00E71D36; element 0 = buffer_va[2])
 *       page_counts[i]  A5 + 0x6E + i*2   (0x00E71B9C; element 0 = the low
 *                                          word of done_cnt)
 *   - the block carries exactly the image's non-zero bytes (the packet info
 *     template's first 0x10 bytes) and NETLOG_$EC is self-linked;
 *   - MODULE_DATA_ADDR gives the image address NETLOG_$CNTL wires
 *     (0x00E71B2C) and the block's end is NETLOG_$DATA_END (0x00E71B30).
 */

#include <stdio.h>
#include <stdint.h>
#include <string.h>

#include "netlog/netlog_internal.h"

static int tests_passed = 0;
static int tests_failed = 0;
static int current_failed = 0;

#define RUN_TEST(name)                                                        \
    do {                                                                      \
        printf("  %-48s", #name);                                             \
        current_failed = 0;                                                   \
        test_##name();                                                        \
        if (current_failed) {                                                 \
            tests_failed++;                                                   \
        } else {                                                              \
            tests_passed++;                                                   \
            printf("PASSED\n");                                               \
        }                                                                     \
    } while (0)

#define CHECK_EQ(expected, actual)                                            \
    do {                                                                      \
        long _e = (long)(expected);                                           \
        long _a = (long)(actual);                                             \
        if (_e != _a) {                                                       \
            if (!current_failed) printf("FAILED\n");                          \
            current_failed = 1;                                               \
            printf("      %s:%d: %s: expected 0x%lx, got 0x%lx\n", __FILE__,  \
                   __LINE__, #actual, (unsigned long)_e, (unsigned long)_a);  \
        }                                                                     \
    } while (0)

#include "../netlog_data.c"

/* Byte offset of a cell of NETLOG_$DATA, taken from the object itself. */
#define N_OFF(p) ((long)((const uint8_t *)(p) - (const uint8_t *)&NETLOG_$DATA))

static void test_block_size_is_the_map_segment(void)
{
    CHECK_EQ(0x84, sizeof(NETLOG_$DATA));
    CHECK_EQ(0x00E85684u, MODULE_DATA_ADDR(NETLOG_$DATA));
    /* NETLOG_$DATA_END, the data-range end cell NETLOG_$CNTL wires */
    CHECK_EQ(NETLOG_WIRE_DATA_END_VA,
             MODULE_DATA_ADDR(NETLOG_$DATA) + sizeof(NETLOG_$DATA));
    CHECK_EQ(NETLOG_WIRE_DATA_START_VA, MODULE_DATA_ADDR(NETLOG_$DATA));
}

static void test_field_displacements(void)
{
    CHECK_EQ(0x00, N_OFF(&NETLOG_$DATA.pkt_info));
    CHECK_EQ(0x20, N_OFF(&NETLOG_$DATA.wired_pages[0]));
    CHECK_EQ(0x44, N_OFF(&NETLOG_$DATA.wired_pages[9]));
    CHECK_EQ(0x48, N_OFF(&NETLOG_$DATA.pkt_type1));
    CHECK_EQ(0x4C, N_OFF(&NETLOG_$DATA.pkt_done_cnt));
    CHECK_EQ(0x50, N_OFF(&NETLOG_$DATA.pkt_entry_cnt));
    CHECK_EQ(0x68, N_OFF(&NETLOG_$DATA.spin_lock));
    CHECK_EQ(0x6C, N_OFF(&NETLOG_$DATA.done_cnt));   /* NETLOG_$DONE_CNT 0xE856F0 */
    CHECK_EQ(0x74, N_OFF(&NETLOG_$DATA.current_buf_ptr));
    CHECK_EQ(0x78, N_OFF(&NETLOG_$DATA.wired_page_count));
    CHECK_EQ(0x7A, N_OFF(&NETLOG_$DATA.send_page_index));
    CHECK_EQ(0x7C, N_OFF(&NETLOG_$DATA.current_buf_index));
    CHECK_EQ(0x7E, N_OFF(&NETLOG_$DATA.initialized));
    CHECK_EQ(0x80, N_OFF(&NETLOG_$DATA.ok_to_send));
}

/* (0x54,A5,D0*1) / (0x5c,A5,D0*1) with D0 = index*4, index 1..2 */
static void test_buffer_tables_are_one_based(void)
{
    CHECK_EQ(0x54 + 1 * 4, N_OFF(&NETLOG_$DATA.buffer_va[1]));
    CHECK_EQ(0x54 + 2 * 4, N_OFF(&NETLOG_$DATA.buffer_va[2]));
    CHECK_EQ(0x5C + 1 * 4, N_OFF(&NETLOG_$DATA.buffer_ppn[1]));   /* 0x60 */
    CHECK_EQ(0x5C + 2 * 4, N_OFF(&NETLOG_$DATA.buffer_ppn[2]));   /* 0x64 */
    /* the ppn bias slot is buffer_va[2] */
    CHECK_EQ((long)(intptr_t)&NETLOG_$DATA.buffer_va[2],
             (long)(intptr_t)&NETLOG_$DATA.buffer_ppn[0]);
}

/* (0x6e,A0), A0 = A5 + index*2, index 1..2 */
static void test_page_counts_are_one_based(void)
{
    CHECK_EQ(0x6E + 1 * 2, N_OFF(&NETLOG_$DATA.page_counts[1]));  /* 0x70 */
    CHECK_EQ(0x6E + 2 * 2, N_OFF(&NETLOG_$DATA.page_counts[2]));  /* 0x72 */
    /* the bias slot is bytes 2..3 of done_cnt */
    CHECK_EQ(N_OFF(&NETLOG_$DATA.done_cnt) + 2, N_OFF(&NETLOG_$DATA.page_counts[0]));
}

static void test_initial_contents(void)
{
    static const uint8_t image_head[16] = {
        0x00, 0x04, 0x00, 0x02, 0x00, 0x02, 0x80, 0x31,
        0x00, 0x01, 0x00, 0x00, 0xFF, 0xFF, 0x00, 0x00,
    };
    const uint8_t *b = (const uint8_t *)&NETLOG_$DATA;
    long nonzero = 0;
    size_t i;

    /* field by field (host byte order does not matter) */
    CHECK_EQ(0x0004, NETLOG_$DATA.pkt_info.flags);
    CHECK_EQ(2, NETLOG_$DATA.pkt_info.routing_type);
    CHECK_EQ(2, NETLOG_$DATA.pkt_info.addr_type);
    CHECK_EQ(0x8031, NETLOG_$DATA.pkt_info.protocol);
    CHECK_EQ(1, NETLOG_$DATA.pkt_info.retry_limit);
    CHECK_EQ(0xFFFF, NETLOG_$DATA.pkt_info.field_0c);

    /* big-endian image bytes, rebuilt from the words */
    for (i = 0; i < 16; i += 2) {
        uint16_t w;
        memcpy(&w, b + i, 2);
        CHECK_EQ((image_head[i] << 8) | image_head[i + 1], w);
    }
    for (i = 16; i < sizeof(NETLOG_$DATA); i++) {
        nonzero += b[i] != 0;
    }
    CHECK_EQ(0, nonzero);
}

static void test_eventcount_is_self_linked(void)
{
    CHECK_EQ(0, NETLOG_$EC.value);
    CHECK_EQ((long)(intptr_t)&NETLOG_$EC, (long)(intptr_t)NETLOG_$EC.waiter_list_head);
    CHECK_EQ((long)(intptr_t)&NETLOG_$EC, (long)(intptr_t)NETLOG_$EC.waiter_list_tail);
}

int main(void)
{
    printf("NETLOG module data (NETLOG_$DATA 0x00E85684)\n");

    RUN_TEST(block_size_is_the_map_segment);
    RUN_TEST(field_displacements);
    RUN_TEST(buffer_tables_are_one_based);
    RUN_TEST(page_counts_are_one_based);
    RUN_TEST(initial_contents);
    RUN_TEST(eventcount_is_self_linked);

    printf("\n%d passed, %d failed\n", tests_passed, tests_failed);
    return tests_failed ? 1 : 0;
}
